{
  "findings": [
    {
      "title": "Cross-reference to non-existent section 99.5",
      "page": 13,
      "quote": "the description already exists in Section 99.5.",
      "severity": "major"
    },
    {
      "title": "Contradictory statements about interim analysis",
      "page": 13,
      "quote": "primary analysis of the study from Section 6.2 Planned Interim Analysis ... as the primary analysis is not an interim analysis and the description already exists in Section 99.5.",
      "severity": "major"
    },
    {
      "title": "Inconsistent section numbering for secondary endpoints",
      "page": 13,
      "quote": "Section 8.4.2 Secondary Endpoints ... Section 4.1.2 Secondary Endpoints",
      "severity": "minor"
    },
    {
      "title": "Removed assessments but later added back",
      "page": 14,
      "quote": "Removed the following assessments from the protocol: Dermatology Life Quality Index (DLQI), Children’s Dermatology Life Quality Index (CDLQI), Hospital Anxiety and Depression Scale (HADS), Patient Oriented Eczema Measure (POEM), ophthalmological examination, body surface area (BSA) involvement of AD, thymus and activation-regulated chemokine (TARC), lactate dehydrogenase (LDH), and immunoglobulin E (IgE), optional RNA sample, and research samples (serum/plasma).",
      "severity": "major"
    },
    {
      "title": "Contradictory removal and addition of POEM and BSA",
      "page": 24,
      "quote": "Added sections to describe the Patient Oriented Eczema Measure (POEM) and Body Surface Area (BSA) involvement of AD to match assessments in the Schedule of Events.",
      "severity": "major"
    },
    {
      "title": "Inconsistent deletion of sections",
      "page": 14,
      "quote": "Section 9.2.2.7 Dermatology Life Quality Index (deleted) ... Section 9.2.2.13 Patient Oriented Eczema Measure (deleted) ... Section 9.2.2.16 Body Surface Area Involvement of Atopic Dermatitis (deleted)",
      "severity": "major"
    },
    {
      "title": "Inconsistent inclusion criterion for disease duration",
      "page": 20,
      "quote": "Changed inclusion criterion #2 to: Patients with chronic hand and/or foot dermatitis diagnosed at least 3 years prior to the screening visit for patients ≥18 years old and at least 1 year prior to the screening visit for patients 12 to <18 years old. Previously, this criterion was: Patients with chronic hand and/or foot dermatitis diagnosed at least 6 months prior to the screening visit.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent exclusion criteria for allergic contact dermatitis",
      "page": 21,
      "quote": "Added a note that patients with a documented diagnosis of allergic contact dermatitis of hands and/or feet, who have a positive patch test reaction at screening will also be excluded from the study, regardless of whether history of current skin exposure to products containing this allergen (current relevance) is present.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent removal of alcohol and drug screens",
      "page": 24,
      "quote": "Removed alcohol and drug screens.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent removal of ophthalmological examination",
      "page": 14,
      "quote": "Section 9.2.3.5 Ophthalmological Examination (deleted)",
      "severity": "minor"
    },
    {
      "title": "Inconsistent removal of TARC, LDH, IgE",
      "page": 14,
      "quote": "thymus and activation-regulated chemokine (TARC), lactate dehydrogenase (LDH), and immunoglobulin E (IgE)",
      "severity": "minor"
    },
    {
      "title": "Inconsistent removal of research samples",
      "page": 14,
      "quote": "optional RNA sample, and research samples (serum/plasma).",
      "severity": "minor"
    }
  ]
}
